"""Build Japanese semantic and transitional catalogs from the Chinese source.

The offline Chinese-to-Japanese model stays under build/ and is never shipped.
Chinese remains the source version stored in every output entry, so localization
cannot affect gameplay identity or rule lookup.
"""

from hashlib import sha256
from pathlib import Path
import json
import re
import sys

ROOT = Path(__file__).resolve().parents[1]
BUILD = ROOT / "build"
DEPS = BUILD / "translation-lite"
MODEL = BUILD / "nllb-200-distilled-600M-ct2-int8"
CACHE = BUILD / "japanese-translation-cache-v8.json"
SOURCE = ROOT / "assets/localization/zh_CN.json"
ENGLISH = ROOT / "assets/localization/en_US.json"
LEGACY_ENGLISH = ROOT / "assets/localization/legacy-en_US.json"
OUTPUT = ROOT / "assets/localization/ja_JP.json"
LEGACY_OUTPUT = ROOT / "assets/localization/legacy-ja_JP.json"
sys.path.insert(0, str(DEPS))

try:
    import ctranslate2
    import sentencepiece as spm
except ImportError:
    ctranslate2 = None
    spm = None

FORMAT = re.compile(r"%(?:[-+ 0#]*)(?:\d+|\*)?(?:\.(?:\d+|\*))?[diouxXfFeEgGaAcsp]")
NAMED = re.compile(r"(?<!\{)\{(?:[A-Za-z_][A-Za-z0-9_.]*|\d+)\}(?!\})")
INDEXED = re.compile(r"(?<!\{)\{p(\d+)\}(?!\})")
TAG = re.compile(r"\[(?:/?[A-Za-z][^\]\n]*|[^\]\n]*=[^\]\n]*)\]")
SPECIAL = {"“": "「", "”": "」", "‘": "『", "’": "』"}
SYMBOL = re.compile(r"[❤♡♥✓✕×＋－→←↑↓◇◆∞—…“”‘’「」『』【】⌊⌋～]")
REPEATED_OUTPUT = re.compile(r"(.{2,8})(?:[ ,、・]*\1){4,}")
TOKENS = [f"[PH{index:03d}]" for index in range(600)]

