# Weak enemies apply basic equipment except on departure.
LEGACY_OVERRIDES.update({
    "行动：施加初级2档拘束具→加固→准备→施加中级3档或高级2档拘束具，随后离场。": "行動：初級段階2の拘束具を装着→補強→準備→中級段階3または上級段階2の拘束具を装着して退場。",
    "生命：%s\n特性：非魔法伤害减半。\n开场：捕缚30/100，固定站姿，上身束缚等级至少1。\n行动：随机施加2件初级1档胶带或加固胶带共2档→捕缚＋10→停顿，循环。没有加固目标时只选施加。\n捕缚效果：每累计消耗2能量，施加1件初级2档胶带，捕缚＋10。余数跨回合保留，无位置仍增加进度。胶带包括眼罩和嘴部胶带。": "HP：{p0}\n特性：魔法以外のダメージを半減。\n初動：捕縛30/100を付与し、立ち姿勢に固定。上半身の拘束レベルは最低1。\n行動：初級段階1のテープ拘束具2個を装着、またはテープを合計2段階補強→捕縛＋10→休止、を繰り返す。補強対象がなければ装着のみ。\n捕縛効果：累計2エネルギー消費ごとに初級段階2のテープ拘束具1個を装着し、捕縛＋10。余りは次ターンへ持ち越す。空きがなくても進度は増加する。テープには目隠しと口のテープを含む。",
    "生命：%s\n开场：散缚，施加2件初级2档拘束具。\n行动：之后随机选招。散缚同开场；翻卷收紧先施加1件初级2档拘束具，再加固1件至3档；躁动膨胀获得1层狂躁。\n狂躁：每层使后续施加数量＋1，不增加加固次数。\n限制：散缚、躁动膨胀不连用，翻卷收紧最多连用2次。可施加原白名单内的普通拘束具（含口球、链接绳），不会替换。": "HP：{p0}\n初動：散縛。初級段階2の拘束具2個を装着。\n行動：以後はランダム。散縛は初動と同じ。巻き締めは初級段階2の拘束具1個を装着後、1個を段階3まで補強。躁動膨張は狂躁1層を獲得。\n狂躁：1層ごとに以後の装着数＋1。補強回数は増えない。\n制限：散縛と躁動膨張は連続使用不可。巻き締めは最大2回連続。元の許可リスト内の通常拘束具（ギャグと連結縄を含む）を装着し、置換は行わない。",
    "生命：%s\n开场：获得%d点仪式，此后每个自身回合结束，施加数量＋%d。\n行动：从第2次行动起持续施加拘束具，数量通常为%d、%d、%d……；每件均为初级2档，含链接绳。\n无位置时：剩余每次施加改为加固1次；也无法加固则结束，不累计到下回合。\n特殊：仪式启动后，打断施加不会阻止数量增长；击败后停止。": "HP：{p0}\n初動：儀式を{p1}獲得。以後、自身のターン終了ごとに装着数が永続的に＋{p2}。\n行動：2回目から拘束具を継続装着。通常は{p3}、{p4}、{p5}個……と増加。全て初級段階2で、連結縄を含む。\n空きがない場合：残りの装着1回につき補強1回に変更。補強もできなければ終了し、次ターンには持ち越さない。\n特殊：儀式開始後は装着を中断されても数量は増加。撃破されると停止。"
})


