LEGACY_OVERRIDES.update({
    "当前每满2点快感，获得1点临时魔力。": "現在の快感2ごとに一時魔力を1得る。",
    "本次获得%d临时魔力。": "今回は一時魔力を{p0}得る。",
    "获得%d临时魔力": "一時魔力を{p0}得る",
    "临时魔力转换需要正数快感间隔。": "一時魔力変換の快感間隔は正の数が必要です。"
})


def main():
    chinese = json.loads(SOURCE.read_text(encoding="utf-8"))
    english = json.loads(ENGLISH.read_text(encoding="utf-8"))
    legacy = json.loads(LEGACY_ENGLISH.read_text(encoding="utf-8"))
    assert chinese["locale"] == "zh_CN" and english["locale"] == "en_US"
    assert set(chinese["messages"]) == set(english["messages"]) == set(UI_OVERRIDES)
    for key, source in chinese["messages"].items():
        assert english["messages"][key]["source"] == source["text"], key

    loaded_cache = json.loads(CACHE.read_text(encoding="utf-8")) if CACHE.exists() else {}
    cache = {}
    for source, text in loaded_cache.items():
        text = normalize_translation(source, text)
        if not invalid_machine_translation(text) and not information_loss(source, text) and not semantic_mismatch(source, text) and literal_numbers_preserved(source, text):
            cache[source] = text
    inputs = sorted({entry["source"] for entry in legacy["messages"]})
    pending = [text for text in inputs if text not in cache and text not in LEGACY_OVERRIDES]
    if pending and (ctranslate2 is None or spm is None):
        raise SystemExit("Missing build/translation-lite dependencies")
    if pending and not MODEL.is_dir():
        raise SystemExit("Missing converted model under build/nllb-200-distilled-600M-ct2-int8")
    processor = spm.SentencePieceProcessor(model_file=str(MODEL / "sentencepiece.bpe.model")) if pending else None
    translator = ctranslate2.Translator(str(MODEL), device="cpu") if pending else None
    for start in range(0, len(pending), 64):
        source_batch = pending[start : start + 64]
        translated_batch = translate_texts(source_batch, processor, translator)
        for text, translated in zip(source_batch, translated_batch):
            translated = normalize_translation(text, translated)
            cache[text] = translated
            if template_parameters(translated) != template_parameters(text):
                raise ValueError(f"placeholder mismatch: {text} -> {translated}")
            if invalid_machine_translation(translated) or information_loss(text, translated) or semantic_mismatch(text, translated) or not literal_numbers_preserved(text, translated):
                raise ValueError(f"invalid translation: {text} -> {translated}")
        CACHE.write_text(json.dumps(cache, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        print(f"translated {min(start + len(source_batch), len(pending))}/{len(pending)}", flush=True)

    semantic = {}
    for key, source in chinese["messages"].items():
        text = UI_OVERRIDES[key]
        assert template_parameters(text) == template_parameters(source["text"]), key
        semantic[key] = {"source": source["text"], "text": text}
    OUTPUT.write_text(json.dumps({"schema_version": 1, "locale": "ja_JP", "messages": semantic}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    messages = []
    for entry in legacy["messages"]:
        assert entry["id"] == "legacy.h" + sha256(entry["source"].encode("utf-8")).hexdigest()[:24]
        if entry["source"] in LEGACY_OVERRIDES:
            raw_text = LEGACY_OVERRIDES[entry["source"]]
            uses_indexed_parameters = indexed_override(entry["source"], raw_text)
        else:
            raw_text = cache[entry["source"]]
            uses_indexed_parameters = False
        text = normalize_translation(entry["source"], raw_text)
        if uses_indexed_parameters:
            assert indexed_override(entry["source"], text), entry["id"]
        else:
            assert template_parameters(text) == template_parameters(entry["source"]), entry["id"]
        assert not information_loss(entry["source"], text), entry["id"]
        assert not semantic_mismatch(entry["source"], text), entry["id"]
        assert literal_numbers_preserved(entry["source"], text), entry["id"]
        if not uses_indexed_parameters:
            text = legacy_target(entry["source"], text)
        messages.append({"id": entry["id"], "source": entry["source"], "text": text})
    messages.sort(key=lambda entry: entry["source"])
    LEGACY_OUTPUT.write_text(json.dumps({"schema_version": 1, "locale": "ja_JP", "messages": messages}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"semantic": len(semantic), "legacy": len(messages)}, ensure_ascii=False))


if __name__ == "__main__":
    main()
